d":"83353c3f-3cd2-4505-8311-f722e720867c","claim_evidence_id":"74b69360-a76e-4a31-8179-08f965eb872d"},{"product_id":"41eb6f09-edc7-4f87-baf8-b0135cfa7082","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","claim_evidence_id":"d8e05fdc-362d-43bb-8f33-e5f6dbe590a6"},{"product_id":"41eb6f09-edc7-4f87-baf8-b0135cfa7082","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","claim_evidence_id":"f68fcfb4-d79b-420b-8900-8b23f19324f1"},{"product_id":"41eb6f09-edc7-4f87-baf8-b0135cfa7082","attribute_id":"8a9c0d9d-11e1-45a6-bd44-a49eadd0d42d","claim_evidence_id":"2bf3d024-fcc6-4b40-ad8e-0f66efdce371"},{"product_id":"41eb6f09-edc7-4f87-baf8-b0135cfa7082","attribute_id":"8a9c0d9d-11e1-45a6-bd44-a49eadd0d42d","claim_evidence_id":"5ef8ac50-9a49-43b7-9198-11d6337c9ce6"}],"anon_private_evidence_boundary":true},"description":"Compare personal task capture, project organization and scheduling in Things 3, native OmniFocus 4 perpetual editions and direct-purchase 2Do Mac. Apple platforms and purchase channels differ; optional Web access, future upgrades and update eligibility have separate costs."}$payload$::jsonb; op jsonb; expected jsonb; actual jsonb;
BEGIN
 PERFORM set_config('lock_timeout','10s',true);
 PERFORM set_config('TimeZone','UTC',true);
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.claim_evidence,software_discovery.evidence_sources,software_discovery.attributes,software_discovery.anchors,software_discovery.problems,software_discovery.audiences,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE id='e1e8ba03-2a50-4858-8bbd-9bc031ed53db' AND status='draft' AND NOT editorially_approved) THEN RAISE EXCEPTION 'PR5.40 route drift or repeated apply'; END IF;
 IF coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)<>data->'snapshot'->'published_products' OR coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)<>data->'snapshot'->'approved_published_routes' THEN RAISE EXCEPTION 'PR5.40 publication drift'; END IF;
 IF NOT has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') OR has_table_privilege('anon','software_discovery.claim_evidence','SELECT') THEN RAISE EXCEPTION 'PR5.40 private evidence boundary drift'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'guards') LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,r))-''created_at''-''updated_at'' j FROM jsonb_array_elements($1) r) x',op->>'table') INTO expected USING op->'rows';
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(t)-''created_at''-''updated_at'' j FROM software_discovery.%I t WHERE %s) x',op->>'table',op->>'where') INTO actual;
  IF expected<>actual THEN RAISE EXCEPTION 'PR5.40 stored baseline drift: %',op->>'table'; END IF;
 END LOOP;
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true,description=data->>'description' WHERE id='e1e8ba03-2a50-4858-8bbd-9bc031ed53db';
 IF (SELECT count(*) FROM software_discovery.products WHERE status='published')<>15 OR (SELECT count(*) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved)<>7 THEN RAISE EXCEPTION 'PR5.40 post-publication count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.products WHERE id IN ('00c746bd-fcb1-46f3-b5a5-cbb3a695fbea','41eb6f09-edc7-4f87-baf8-b0135cfa7082','376772e0-a043-4cb6-b87f-d18750ee5548') AND software_discovery.product_discovery_page(slug) IS NULL) THEN RAISE EXCEPTION 'PR5.40 public product projection missing'; END IF;
 -- Owner-approved apply persists.
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN RAISE NOTICE 'Task route publication rehearsal rolled back; no changes persisted';
END $task_publish$;
